    // Editor-only embedded source images. Materials reference persistent native Texture2D assets,
    // so missing PNG files or an unavailable PNG import artifact cannot break the model setup.
    internal static class FreeModelsTextureRecovery
    {
        private const string Root = "Assets/FreeModels_ImportFixed_20261026";
        private const string NativeFolder = Root + "/Textures/NativeTexturesV4";
        private static readonly Dictionary<string, Texture2D> Cache = new Dictionary<string, Texture2D>(StringComparer.OrdinalIgnoreCase);

        internal static Texture2D Load(string relativePath)
        {
            string name = Path.GetFileName(relativePath.Replace('\\', '/'));
            Texture2D texture;
            if (Cache.TryGetValue(name, out texture) && texture != null) return texture;
            EnsureFolder(NativeFolder);
            string assetPath = NativeFolder + "/" + Path.GetFileNameWithoutExtension(name) + ".asset";
            texture = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
            if (texture != null)
            {
                Cache[name] = texture;
                return texture;
            }
            if (File.Exists(Path.GetFullPath(assetPath)))
                assetPath = AssetDatabase.GenerateUniqueAssetPath(assetPath);
            byte[] png = GetPngBytes(name);
            texture = new Texture2D(2, 2, TextureFormat.RGBA32, false, false);
            if (!ImageConversion.LoadImage(texture, png, false))
            {
                UnityEngine.Object.DestroyImmediate(texture);
                throw new InvalidDataException("내장 텍스처 해독 실패: " + name);
            }
            texture.name = Path.GetFileNameWithoutExtension(name);
            texture.filterMode = FilterMode.Point;
            texture.wrapMode = TextureWrapMode.Clamp;
            texture.anisoLevel = 0;
            texture.Apply(false, false);
            AssetDatabase.CreateAsset(texture, assetPath);
            Cache[name] = texture;
            return texture;
        }

        private static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            string parent = Path.GetDirectoryName(path).Replace('\\', '/');
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
        }

